import html2pdf from 'html2pdf.js';

/**
 * Converts invoice HTML content directly into a downloadable .pdf file.
 * @param htmlContent HTML string generated by invoice template
 * @param filename Target filename for the PDF download (e.g. Bill_of_Supply_SO-1001)
 * @param is3Inch True for 3-inch thermal bill format, False for A4 tax invoice format
 */
export async function downloadHtmlAsPdf(
  htmlContent: string,
  filename: string,
  is3Inch: boolean = false
): Promise<void> {
  const container = document.createElement('div');
  container.className = 'pdf-export-container';
  container.style.position = 'fixed';
  container.style.top = '-9999px';
  container.style.left = '-9999px';
  container.style.width = is3Inch ? '80mm' : '210mm';
  container.style.backgroundColor = '#ffffff';
  container.style.color = '#000000';
  container.innerHTML = htmlContent;
  document.body.appendChild(container);

  const cleanFilename = filename.toLowerCase().endsWith('.pdf')
    ? filename
    : `${filename}.pdf`;

  const marginVal: [number, number, number, number] = is3Inch ? [2, 2, 2, 2] : [6, 6, 6, 6];

  const opt = {
    margin: marginVal,
    filename: cleanFilename,
    image: { type: 'jpeg' as const, quality: 0.98 },
    html2canvas: { scale: 2, useCORS: true, logging: false },
    jsPDF: is3Inch
      ? { unit: 'mm' as const, format: [80, 220] as [number, number], orientation: 'portrait' as const }
      : { unit: 'mm' as const, format: 'a4', orientation: 'portrait' as const }
  };

  try {
    await html2pdf().set(opt).from(container).save();
  } catch (err) {
    console.error('Failed to generate PDF via html2pdf, opening print fallback:', err);
    const printWin = window.open('', '_blank');
    if (printWin) {
      printWin.document.write(htmlContent);
      printWin.document.close();
      setTimeout(() => {
        printWin.focus();
        printWin.print();
      }, 500);
    }
  } finally {
    if (document.body.contains(container)) {
      document.body.removeChild(container);
    }
  }
}
